      const options = [
        { id: "notifications-email", value: "email", label: "Email" },
        { id: "notifications-sms", value: "sms", label: "SMS" },
        {
          id: "notifications-push",
          value: "push-notifications",
          label: "Push Notifications",
        },
      ];

      const RadioOption = ({ id, value, label }) => `
        <div class="radio-option">
          <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
          <label class="radio-card" for="${id}">${label}</label>
        </div>
      `;

