  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const options = [
        { id: "notifications-email", value: "email", label: "Email" },
        { id: "notifications-sms", value: "sms", label: "SMS" },
        {
          id: "notifications-push",
          value: "push-notifications",
          label: "Push Notifications",
        },
      ];

      const RadioOption = ({ id, value, label }) => `
        <div class="radio-option">
          <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
          <label class="radio-card" for="${id}">${label}</label>
        </div>
      `;

      const NotificationPreferenceField = () => `
        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-error">
            <legend>
              How do you prefer to receive notifications?
              <span aria-hidden="true">*</span>
            </legend>
            <p class="required-note">Required fields are marked with an asterisk.</p>
            <p id="notification-help" class="field-help">Choose one notification method.</p>
            <p id="notification-error" class="field-error" aria-live="assertive"></p>
            <div class="options">
              ${options.map(RadioOption).join("")}
            </div>
          </fieldset>
        </div>
      `;

      const NotificationForm = () => `
        <form id="notification-form" novalidate>
          ${NotificationPreferenceField()}
          <div class="actions">
            <button type="submit">Save preference</button>
            <p id="form-status" class="status" aria-live="polite"></p>
          </div>
        </form>
      `;

      const App = () => `
        <main id="main-content" class="page-shell">
          <section class="product-card" aria-labelledby="page-title">
            <p class="eyebrow">Notification settings</p>
            <h1 id="page-title">Stay in the loop</h1>
            <p class="intro">
              Pick the channel that works best for timely product updates,
              account alerts, and reminders.
            </p>
            ${NotificationForm()}
          </section>
        </main>
      `;

      document.getElementById("root").innerHTML = App();

      document
        .getElementById("notification-form")
        .addEventListener("submit", (event) => {
          event.preventDefault();

          const form = event.currentTarget;
          const radios = form.querySelectorAll('input[name="notificationPreference"]');
          const selected = form.querySelector('input[name="notificationPreference"]:checked');
          const error = document.getElementById("notification-error");
          const status = document.getElementById("form-status");

          if (!selected) {
            form.querySelector('input[name="notificationPreference"]').focus();
            radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
            error.textContent = "Error: Choose one notification method before saving.";
            status.textContent = "";
            return;
          }

          radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
          error.textContent = "";
          const selectedLabel = form.querySelector(`label[for="${selected.id}"]`).textContent;
          status.textContent = `Preference saved: ${selectedLabel}.`;
        });
    </script>
  </body>
